settings.custom_css:
selector .eael-post-list-thumbnail { height: 300px; display: flex; align-items: center; justify-content: center; overflow: hidden; }
selector .eael-post-list-thumbnail a { display: flex; width: 100%; height: 100%; align-items: center; justify-content: center; }
selector .eael-post-list-thumbnail img { max-height: 100%; max-width: 100%; width: auto; height: auto; object-fit: contain; margin: 0 auto; }
